*** Begin Patch
*** Add File: output/assets/styles.css
+:root{
+  --bg:#111;
+  --bg-2:#141414;
+  --panel:#171717;
+  --panel-2:#1f1f1f;
+  --text:#f5f7fb;
+  --muted:#b8beca;
+  --line:rgba(255,255,255,.10);
+  --red:#E63946;
+  --red-2:#FF0000;
+  --shadow:0 18px 45px rgba(0,0,0,.55);
+  --radius:18px;
+  --radius-sm:12px;
+  --container:1180px;
+  --headline:"Oswald",system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
+  --body:"Inter",system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
+}
+
+*{box-sizing:border-box}
+html,body{height:100%}
+body{
+  margin:0;
+  font-family:var(--body);
+  color:var(--text);
+  background:
+    radial-gradient(900px 400px at 15% 0%, rgba(230,57,70,.22), transparent 55%),
+    radial-gradient(800px 420px at 90% 10%, rgba(255,0,0,.12), transparent 55%),
+    linear-gradient(180deg, #0f0f0f 0%, var(--bg) 30%, #0b0b0b 100%);
+  letter-spacing:.2px;
+}
+
+a{color:inherit; text-decoration:none}
+img{max-width:100%; display:block}
+
+.container{max-width:var(--container); margin:0 auto; padding:0 22px}
+
+.skip-link{position:absolute; left:-999px; top:auto; width:1px; height:1px; overflow:hidden}
+.skip-link:focus{left:14px; top:14px; width:auto; height:auto; padding:10px 12px; background:var(--panel); border:1px solid var(--line); border-radius:12px; z-index:9999}
+
+.topbar{
+  background:linear-gradient(90deg, rgba(230,57,70,.22), rgba(230,57,70,.06));
+  border-bottom:1px solid rgba(230,57,70,.28);
+}
+.topbar .inner{display:flex; align-items:center; justify-content:space-between; gap:14px; padding:9px 0; font-size:13px; color:var(--muted)}
+.topbar strong{color:var(--text); font-weight:700}
+
+.btn{
+  display:inline-flex; align-items:center; justify-content:center;
+  gap:10px;
+  border:1px solid var(--line);
+  border-radius:999px;
+  padding:12px 16px;
+  background:rgba(255,255,255,.04);
+  color:var(--text);
+  font-weight:700;
+  letter-spacing:.6px;
+  text-transform:uppercase;
+  font-size:13px;
+  transition:transform .2s ease, background .2s ease, border-color .2s ease;
+  cursor:pointer;
+  user-select:none;
+}
+.btn:hover{transform:translateY(-1px); background:rgba(255,255,255,.06)}
+.btn:active{transform:translateY(0)}
+.btn-primary{background:linear-gradient(180deg, rgba(230,57,70,1), rgba(166,22,33,1)); border-color:rgba(230,57,70,.6); box-shadow:0 10px 28px rgba(230,57,70,.25)}
+.btn-primary:hover{background:linear-gradient(180deg, rgba(255,0,0,1), rgba(166,22,33,1));}
+.btn-ghost{background:transparent}
+.btn-small{padding:10px 13px; font-size:12px}
+
+.pill{display:inline-flex; align-items:center; gap:8px; padding:8px 10px; border:1px solid var(--line); border-radius:999px; background:rgba(255,255,255,.03); color:var(--muted); font-size:12px; letter-spacing:.35px}
+
+.navwrap{position:sticky; top:0; z-index:50; backdrop-filter:blur(10px)}
+.navbar{
+  border-bottom:1px solid var(--line);
+  background:rgba(10,10,10,.55);
+}
+.navbar .inner{display:flex; align-items:center; justify-content:space-between; gap:18px; padding:14px 0}
+.logo{display:flex; align-items:center; gap:10px; font-family:var(--headline); text-transform:uppercase; letter-spacing:1.2px; font-size:20px}
+.mark{width:12px; height:12px; border-radius:2px; background:var(--red); box-shadow:0 0 22px rgba(230,57,70,.55)}
+.navlinks{display:flex; align-items:center; gap:18px; flex-wrap:wrap}
+.navlinks a{color:var(--muted); font-weight:700; text-transform:uppercase; font-size:12px; letter-spacing:.7px; padding:10px 10px; border-radius:999px; transition:background .2s ease, color .2s ease}
+.navlinks a:hover{background:rgba(255,255,255,.05); color:var(--text)}
+.navlinks a[aria-current="page"]{background:rgba(230,57,70,.14); border:1px solid rgba(230,57,70,.28); color:var(--text)}
+
+.navactions{display:flex; align-items:center; gap:10px}
+
+.mobile-toggle{display:none}
+
+.hero{
+  position:relative;
+  padding:70px 0 26px;
+}
+
+.hero-grid{display:grid; grid-template-columns:1.2fr .8fr; gap:28px; align-items:stretch}
+
+.hero-card{
+  border:1px solid rgba(255,255,255,.10);
+  background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
+  border-radius:var(--radius);
+  padding:28px;
+  box-shadow:var(--shadow);
+  overflow:hidden;
+  position:relative;
+}
+.hero-card::after{
+  content:"";
+  position:absolute;
+  inset:-120px -160px auto auto;
+  width:320px;
+  height:320px;
+  background:radial-gradient(circle at 30% 30%, rgba(230,57,70,.60), transparent 55%);
+  filter:blur(3px);
+  transform:rotate(20deg);
+  opacity:.65;
+}
+
+.eyebrow{font-family:var(--headline); letter-spacing:2px; text-transform:uppercase; color:rgba(230,57,70,.95); font-size:14px}
+h1,h2,h3{font-family:var(--headline); text-transform:uppercase; margin:0 0 10px; letter-spacing:1px}
+h1{font-size:56px; line-height:1.02}
+.lead{color:var(--muted); font-size:16px; line-height:1.7; max-width:62ch}
+.hero-actions{display:flex; gap:12px; flex-wrap:wrap; margin-top:18px}
+
+.hero-aside{
+  border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.10);
+  background:
+    linear-gradient(180deg, rgba(230,57,70,.12), rgba(255,255,255,.02)),
+    radial-gradient(900px 420px at 20% 10%, rgba(255,0,0,.16), transparent 50%);
+  box-shadow:var(--shadow);
+  padding:22px;
+  display:flex;
+  flex-direction:column;
+  justify-content:space-between;
+  position:relative;
+  overflow:hidden;
+}
+
+.stat{display:grid; grid-template-columns:auto 1fr; gap:10px; align-items:start; padding:14px 0; border-bottom:1px solid rgba(255,255,255,.10)}
+.stat:last-child{border-bottom:none}
+.stat .num{font-family:var(--headline); font-size:34px; line-height:1; color:var(--text)}
+.stat .lbl{color:var(--muted); font-weight:600; font-size:13px}
+.stat .sub{color:rgba(255,255,255,.78); font-size:13px; line-height:1.5}
+
+section{padding:44px 0}
+
+.section-head{display:flex; align-items:end; justify-content:space-between; gap:14px; margin-bottom:18px}
+.section-head h2{font-size:34px}
+.section-head p{margin:0; color:var(--muted); max-width:70ch; line-height:1.6}
+
+.grid-2{display:grid; grid-template-columns:1fr 1fr; gap:18px}
+.grid-3{display:grid; grid-template-columns:repeat(3, 1fr); gap:16px}
+
+.card{
+  border:1px solid rgba(255,255,255,.10);
+  background:linear-gradient(180deg, rgba(255,255,255,.03), rgba(255,255,255,.015));
+  border-radius:var(--radius);
+  padding:18px;
+  box-shadow:0 12px 36px rgba(0,0,0,.38);
+}
+.card h3{font-size:22px; margin-bottom:6px}
+.card p{color:var(--muted); margin:0; line-height:1.65}
+.card .meta{margin-top:12px; display:flex; gap:10px; flex-wrap:wrap}
+
+.split{
+  display:grid;
+  grid-template-columns:1.1fr .9fr;
+  gap:18px;
+  align-items:stretch;
+}
+
+.media{
+  border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.10);
+  overflow:hidden;
+  background:linear-gradient(180deg, rgba(230,57,70,.16), rgba(0,0,0,.2));
+  min-height:280px;
+  box-shadow:var(--shadow);
+  position:relative;
+}
+.media::before{
+  content:"";
+  position:absolute;
+  inset:0;
+  background:
+    radial-gradient(700px 280px at 18% 12%, rgba(230,57,70,.35), transparent 55%),
+    radial-gradient(600px 280px at 85% 18%, rgba(255,0,0,.20), transparent 55%),
+    linear-gradient(180deg, rgba(0,0,0,.12), rgba(0,0,0,.68));
+}
+.media .caption{
+  position:absolute;
+  inset:auto 0 0 0;
+  padding:18px;
+}
+.caption .tag{display:inline-flex; align-items:center; gap:8px; font-weight:800; text-transform:uppercase; letter-spacing:1px; font-size:12px; color:rgba(255,255,255,.82)}
+
+.cta-band{
+  border-radius:calc(var(--radius) + 4px);
+  background:linear-gradient(90deg, rgba(230,57,70,.18), rgba(255,255,255,.02));
+  border:1px solid rgba(230,57,70,.30);
+  padding:24px;
+  box-shadow:0 18px 44px rgba(0,0,0,.46);
+}
+.cta-band h2{font-size:40px; margin-bottom:6px}
+.cta-band p{margin:0; color:rgba(255,255,255,.82); line-height:1.6}
+.cta-band .row{display:flex; align-items:center; justify-content:space-between; gap:14px; flex-wrap:wrap}
+
+.carousel{
+  border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.10);
+  background:rgba(0,0,0,.28);
+  overflow:hidden;
+  box-shadow:var(--shadow);
+}
+.carousel .viewport{overflow:hidden}
+.carousel .track{display:flex; will-change:transform; transition:transform .45s cubic-bezier(.2,.9,.2,1)}
+.slide{min-width:100%; position:relative}
+.slide .img{
+  height:380px;
+  background:linear-gradient(135deg, rgba(230,57,70,.30), rgba(0,0,0,.65));
+  position:relative;
+}
+.slide .img::after{
+  content:"";
+  position:absolute;
+  inset:0;
+  background:linear-gradient(180deg, rgba(0,0,0,.15), rgba(0,0,0,.78));
+}
+.slide .overlay{position:absolute; inset:auto 0 0 0; padding:18px}
+.slide .overlay h3{font-size:28px; margin:0 0 4px}
+.slide .overlay p{margin:0; color:rgba(255,255,255,.78); line-height:1.55}
+
+.carousel .controls{display:flex; align-items:center; justify-content:space-between; gap:12px; padding:12px 12px; border-top:1px solid rgba(255,255,255,.10)}
+.dots{display:flex; gap:8px; align-items:center}
+.dot{width:8px; height:8px; border-radius:999px; background:rgba(255,255,255,.25); border:1px solid rgba(255,255,255,.20)}
+.dot[aria-current="true"]{background:rgba(230,57,70,.85); border-color:rgba(230,57,70,.75); box-shadow:0 0 0 6px rgba(230,57,70,.16)}
+
+.form{
+  border-radius:var(--radius);
+  border:1px solid rgba(255,255,255,.10);
+  background:linear-gradient(180deg, rgba(255,255,255,.03), rgba(255,255,255,.015));
+  padding:18px;
+  box-shadow:0 12px 38px rgba(0,0,0,.42);
+}
+.form .row{display:flex; gap:10px; flex-wrap:wrap; align-items:flex-start}
+label{display:block; font-weight:700; text-transform:uppercase; letter-spacing:.8px; font-size:12px; color:rgba(255,255,255,.8); margin-bottom:8px}
+input,select{
+  width:100%;
+  border-radius:999px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(0,0,0,.25);
+  padding:12px 14px;
+  color:var(--text);
+  outline:none;
+  font-size:14px;
+}
+input:focus,select:focus{border-color:rgba(230,57,70,.55); box-shadow:0 0 0 4px rgba(230,57,70,.18)}
+.field{flex:1 1 260px}
+.feedback{margin-top:10px; font-size:13px}
+.feedback.error{color:#ffb4bb}
+.feedback.ok{color:#b8ffcf}
+
+.table-wrap{
+  border:1px solid rgba(255,255,255,.10);
+  border-radius:var(--radius);
+  overflow:hidden;
+  background:rgba(0,0,0,.24);
+  box-shadow:0 12px 38px rgba(0,0,0,.42);
+}
+table{width:100%; border-collapse:collapse}
+th,td{padding:14px 16px; text-align:left; border-bottom:1px solid rgba(255,255,255,.08)}
+th{font-size:12px; text-transform:uppercase; letter-spacing:1px; color:rgba(255,255,255,.75); background:rgba(255,255,255,.03)}
+td{color:rgba(255,255,255,.86)}
+tbody tr:hover{background:rgba(230,57,70,.08)}
+
+.toggle{
+  display:inline-flex;
+  border-radius:999px;
+  padding:4px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(0,0,0,.25);
+  gap:4px;
+}
+.toggle button{
+  border:none;
+  background:transparent;
+  color:rgba(255,255,255,.75);
+  font-weight:900;
+  text-transform:uppercase;
+  letter-spacing:.9px;
+  padding:10px 14px;
+  border-radius:999px;
+  cursor:pointer;
+  transition:background .2s ease, color .2s ease;
+}
+.toggle button[aria-pressed="true"]{background:rgba(230,57,70,.16); color:var(--text); border:1px solid rgba(230,57,70,.28)}
+
+.filters{display:flex; gap:12px; flex-wrap:wrap; align-items:end}
+
+.instructor-card{display:grid; grid-template-columns:96px 1fr; gap:14px; align-items:center}
+.avatar{
+  width:96px; height:96px; border-radius:18px;
+  border:1px solid rgba(255,255,255,.12);
+  background:linear-gradient(135deg, rgba(230,57,70,.35), rgba(0,0,0,.6));
+  position:relative;
+  overflow:hidden;
+}
+.avatar::after{content:""; position:absolute; inset:0; background:radial-gradient(circle at 30% 20%, rgba(255,255,255,.14), transparent 45%)}
+.instructor-card .name{font-family:var(--headline); text-transform:uppercase; letter-spacing:1px; font-size:22px; margin:0}
+.instructor-card .loc{margin:2px 0 10px; color:var(--muted); font-weight:600}
+
+.faq{border-radius:var(--radius); border:1px solid rgba(255,255,255,.10); overflow:hidden; box-shadow:0 12px 38px rgba(0,0,0,.42)}
+.faq-item{border-bottom:1px solid rgba(255,255,255,.08); background:rgba(0,0,0,.22)}
+.faq-item:last-child{border-bottom:none}
+.faq-q{width:100%; text-align:left; padding:16px; background:transparent; border:none; color:var(--text); display:flex; align-items:center; justify-content:space-between; gap:16px; cursor:pointer}
+.faq-q strong{font-family:var(--headline); text-transform:uppercase; letter-spacing:1px; font-size:20px}
+.faq-a{padding:0 16px 16px; color:rgba(255,255,255,.78); line-height:1.7; display:none}
+.faq-item[data-open="true"] .faq-a{display:block}
+.chev{width:20px; height:20px; border-radius:999px; border:1px solid rgba(255,255,255,.15); display:grid; place-items:center; flex:0 0 auto; background:rgba(255,255,255,.03)}
+.faq-item[data-open="true"] .chev{border-color:rgba(230,57,70,.45); background:rgba(230,57,70,.12)}
+
+.footer{border-top:1px solid rgba(255,255,255,.10); padding:34px 0; background:rgba(0,0,0,.30)}
+.footer-grid{display:grid; grid-template-columns:2fr 1fr 1fr 1fr; gap:18px}
+.footer h3{font-size:18px; margin:0 0 10px}
+.footer a{display:block; color:var(--muted); padding:7px 0}
+.footer a:hover{color:var(--text)}
+.footnote{margin-top:18px; color:rgba(255,255,255,.52); font-size:12px; display:flex; gap:10px; flex-wrap:wrap; align-items:center; justify-content:space-between}
+
+.dropdown{position:relative; display:inline-flex; align-items:center; gap:10px}
+.dropdown-panel{
+  position:absolute;
+  right:0;
+  bottom:calc(100% + 10px);
+  min-width:220px;
+  border-radius:16px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(18,18,18,.98);
+  box-shadow:0 18px 48px rgba(0,0,0,.65);
+  overflow:hidden;
+  display:none;
+}
+.dropdown-panel[aria-hidden="false"]{display:block}
+.dropdown-panel button{
+  width:100%;
+  padding:12px 14px;
+  text-align:left;
+  border:none;
+  background:transparent;
+  color:var(--text);
+  cursor:pointer;
+}
+.dropdown-panel button:hover{background:rgba(230,57,70,.12)}
+
+.sr-only{position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0}
+
+@media (max-width: 980px){
+  h1{font-size:44px}
+  .hero-grid{grid-template-columns:1fr;}
+  .split{grid-template-columns:1fr;}
+  .grid-3{grid-template-columns:1fr;}
+  .footer-grid{grid-template-columns:1fr 1fr;}
+}
+
+@media (max-width: 720px){
+  .navlinks{display:none}
+  .mobile-toggle{display:inline-flex}
+  .navlinks[data-open="true"]{display:flex; flex-direction:column; align-items:stretch; width:100%; padding-bottom:12px}
+  .navbar .inner{flex-wrap:wrap}
+  .navactions{width:100%; justify-content:space-between}
+  .slide .img{height:320px}
+  .footer-grid{grid-template-columns:1fr}
+}
+
*** End Patch

